<?php
// Isolated tests: no production rows, mail, jobs, or live payment requests.
$root=$argv[1]; $module=$argv[2];
require $root.'/vendor/autoload.php';
$app=require $root.'/bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\{DB,Schema,Http,Mail,Queue};
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Http\Request;
use App\Models\{User,TagPurchase};
use App\Services\PickupPaymentVerifier;
use App\Http\Controllers\Api\PickupReceiptController;
config(['database.default'=>'it_pickup_memory','database.connections.it_pickup_memory'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true], 'cache.default'=>'array','app.key'=>'base64:'.base64_encode(str_repeat('K',32))]);
DB::setDefaultConnection('it_pickup_memory');
if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:') throw new RuntimeException('Memory guard failed');
Mail::fake(); Queue::fake(); Http::preventStrayRequests();
require $module.'/app/Services/PickupPaymentVerifier.php';
require $module.'/app/Http/Controllers/Api/PickupReceiptController.php';
Schema::create('points_of_sale',function(Blueprint $t){$t->id();$t->string('name');$t->boolean('active');$t->softDeletes();$t->timestamps();});
Schema::create('tags',function(Blueprint $t){$t->id();$t->string('name');$t->softDeletes();$t->timestamps();});
Schema::create('tags_purchases',function(Blueprint $t){$t->id();$t->unsignedBigInteger('user_id');$t->unsignedBigInteger('tag_id');$t->unsignedBigInteger('vehicle_id');$t->integer('qty');$t->string('price_total');$t->string('shipping_price')->default('0');$t->text('pickup_point')->nullable();$t->text('delivery')->nullable();$t->string('mp_payment_id');$t->string('payment_method');$t->integer('status');$t->softDeletes();$t->timestamps();});
Schema::create('shipments',function(Blueprint $t){$t->id();$t->unsignedBigInteger('tag_purchase_id');$t->integer('status')->default(0);$t->string('carrier');$t->timestamp('delivered_at')->nullable();$t->string('last_event')->nullable();$t->softDeletes();$t->timestamps();});
(require $module.'/database/migrations/2026_11_02_200000_create_pickup_receipts_table.php')->up();
DB::table('points_of_sale')->insert([['id'=>1,'name'=>'Preferido','active'=>1],['id'=>2,'name'=>'Outro ponto','active'=>1],['id'=>3,'name'=>'Inativo','active'=>0]]);
DB::table('tags')->insert(['id'=>1,'name'=>'Azul']);
DB::table('tags_purchases')->insert(['id'=>1,'user_id'=>10,'tag_id'=>1,'vehicle_id'=>1,'qty'=>1,'price_total'=>'29.90','shipping_price'=>'0','pickup_point'=>json_encode(['id'=>1]),'mp_payment_id'=>'123456789','payment_method'=>'pix','status'=>1]);
$customer=(new User)->forceFill(['id'=>10,'type'=>3]); $other=(new User)->forceFill(['id'=>11,'type'=>3]);
$staff=(new User)->forceFill(['id'=>20,'type'=>2,'pdv_id'=>2]); $inactive=(new User)->forceFill(['id'=>21,'type'=>2,'pdv_id'=>3]);
$request=function(User $user,array $body=[]){$r=Request::create('/qa','POST',$body);$r->setUserResolver(fn()=>$user);return $r;};
$checks=0;
$ok=function(bool $value,string $label)use(&$checks){if(!$value)throw new RuntimeException($label);$checks++;};
$fails=function(callable $call,int $status,string $label)use($ok){try{$call();throw new RuntimeException('Unexpected success: '.$label);}catch(Illuminate\Database\Eloquent\ModelNotFoundException $e){$ok($status===404,$label);}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){$ok($e->getStatusCode()===$status,$label);}};
$controller=new PickupReceiptController; $verifier=new PickupPaymentVerifier;
$fails(fn()=>$controller->issue($request($other),1),404,'another customer cannot issue');
$issued=$controller->issue($request($customer),1)->getData(true);
$token=explode('#',$issued['receipt_url'])[1];
$ok(preg_match('/^[a-f0-9]{64}$/',$token)===1,'opaque random code');
$ok(!str_contains($issued['receipt_url'],'?'),'no personal data in query');
$again=$controller->issue($request($customer),1)->getData(true);
$ok($again['receipt_url']===$issued['receipt_url']&&DB::table('pickup_receipts')->count()===1,'stable unique receipt');
$ok(DB::table('pickup_receipts')->value('encrypted_token')!==$token,'encrypted token at rest');
$payment=['id'=>123456789,'status'=>'approved','live_mode'=>true,'currency_id'=>'BRL','transaction_amount'=>29.90,'transaction_amount_refunded'=>0];
$fake=function(array $body,int $status=200){Http::swap(new Illuminate\Http\Client\Factory);Http::preventStrayRequests();Http::fake(['*'=>Http::response($body,$status)]);}; $fake($payment);
config(['mercadopago.access_token'=>'test-only-not-a-secret']);
$fails(fn()=>$controller->verify($request($customer,['token'=>$token]),$verifier),403,'customer cannot verify or collect');
$fails(fn()=>$controller->verify($request($inactive,['token'=>$token]),$verifier),404,'inactive point denied');
$fails(fn()=>$controller->verify($request($staff,['token'=>str_repeat('f',64)]),$verifier),404,'invalid receipt denied');
foreach(['pending','rejected','refunded','charged_back'] as $status){$p=$payment;$p['status']=$status;$fake($p);$fails(fn()=>$controller->collect($request($staff,['token'=>$token]),$verifier),409,'reject '.$status);}
foreach([['transaction_amount',19.90],['transaction_amount_refunded',1],['currency_id','USD'],['live_mode',false],['id',999]] as [$field,$value]){$p=$payment;$p[$field]=$value;$fake($p);$fails(fn()=>$controller->collect($request($staff,['token'=>$token]),$verifier),409,'reject altered '.$field);}
$fake([],503);$fails(fn()=>$controller->collect($request($staff,['token'=>$token]),$verifier),503,'provider offline fails closed');
$ok(DB::table('pickup_receipts')->value('collected_at')===null&&DB::table('shipments')->count()===0,'failed checks do not deliver');
$fake($payment);
$verified=$controller->verify($request($staff,['token'=>$token,'point_id'=>1]),$verifier)->getData(true);
$ok($verified['point_name']==='Outro ponto'&&!$verified['collected'],'any active point and own staff identity');
$ok(!isset($verified['payer'])&&!isset($verified['receipt_url']),'minimal staff response');
$collected=$controller->collect($request($staff,['token'=>$token]),$verifier)->getData(true);
$ok($collected['collected']&&DB::table('pickup_receipts')->value('collected_point_id')===2,'actual point recorded');
$ok(DB::table('shipments')->value('status')===4,'legacy shipment marked collected');
$fails(fn()=>$controller->collect($request($staff,['token'=>$token]),$verifier),409,'second collection denied');
$ok(DB::table('pickup_receipts')->count()===1,'one receipt per order');
echo 'PASS '.$checks.' isolated pickup checks; no real payments, mail or production writes.'.PHP_EOL;
